TRANSLATIONS = {locale: {} for locale in LOCALES}
for row in _ROWS.strip().splitlines():
    key, *values = row.split('|')
    if len(values) != len(LOCALES) or key in TRANSLATIONS['en']:
        raise ValueError(f'Invalid translation row: {key}')
    for locale, value in zip(LOCALES, values):
        TRANSLATIONS[locale][key] = value
